// Builds supabase/seeds/interview-questions.sql (the pharmacy-careers interview bank, prompts/18)
// from supabase/seeds/source/interview-questions.json.
// Run: node scripts/build-interview-seed.mjs   then   npm run db:push
// (db push skips a seed file it has already applied: run a regenerated file with the Supabase MCP
// execute_sql instead; it's idempotent.)
//
// Ids are md5('interview:' || key), so the seed can run again. Questions missing from the source
// are deactivated (never deleted: past sessions copied their text, but keep the reference).

import { readFileSync, writeFileSync } from "node:fs";

const SOURCE = "supabase/seeds/source/interview-questions.json";
const OUTPUT = "supabase/seeds/interview-questions.sql";
const KINDS = new Set(["behavioural", "situational", "motivation"]);
const SETTINGS = ["foundation", "community", "hospital", "placement"];

const { categories, questions } = JSON.parse(readFileSync(SOURCE, "utf8"));
const problems = [];
const keys = new Set();

for (const q of questions) {
  const where = q.key ?? "(no key)";
  if (!/^[a-z0-9-]+$/.test(q.key ?? "")) problems.push(`${where}: key must be kebab-case`);
  if (keys.has(q.key)) problems.push(`${where}: duplicate key`);
  keys.add(q.key);
  if (!categories[q.category]) problems.push(`${where}: unknown category ${q.category}`);
  if (!KINDS.has(q.kind)) problems.push(`${where}: unknown kind ${q.kind}`);
  if (!Array.isArray(q.settings) || q.settings.some((s) => !SETTINGS.includes(s))) problems.push(`${where}: bad settings`);
  if (typeof q.prompt !== "string" || q.prompt.trim().length < 15 || q.prompt.length > 300) problems.push(`${where}: prompt length`);
  if (!Array.isArray(q.keyPoints) || q.keyPoints.length < 3 || q.keyPoints.length > 5) problems.push(`${where}: needs 3-5 key points`);
}
for (const category of Object.keys(categories)) {
  const count = questions.filter((q) => q.category === category).length;
  if (count < 6) problems.push(`category ${category}: ${count} questions (needs at least 6)`);
}
for (const setting of SETTINGS) {
  const count = questions.filter((q) => q.settings.includes(setting)).length;
  if (count < 2) problems.push(`setting ${setting}: ${count} tagged questions (needs at least 2)`);
}
// Every target must be able to fill a session: a motivation question + 4 other categories.
for (const setting of SETTINGS) {
  const usable = questions.filter((q) => q.settings.length === 0 || q.settings.includes(setting));
  const others = new Set(usable.filter((q) => q.category !== "motivation").map((q) => q.category));
  if (!usable.some((q) => q.category === "motivation") || others.size < 4) problems.push(`setting ${setting}: can't fill a session`);
}
if (problems.length) {
  console.error(problems.join("\n"));
  process.exit(1);
}

const sql = (value) => `'${String(value).replaceAll("'", "''")}'`;
const array = (values) => (values.length ? `array[${values.map(sql).join(", ")}]::text[]` : "'{}'::text[]");

const rows = questions.map(
  (q) =>
    `  (md5(${sql(`interview:${q.key}`)})::uuid, ${sql(q.key)}, ${sql(q.category)}, ${sql(q.kind)}, ${array(q.settings)},\n` +
    `   ${sql(q.prompt.trim())},\n   ${array(q.keyPoints.map((p) => p.trim()))}, true)`,
);

const out = [
  "-- Generated by scripts/build-interview-seed.mjs from supabase/seeds/source/interview-questions.json.",
  "-- Do not edit by hand: change the source or the script and run it again.",
  "",
  "insert into public.interview_questions (id, key, category, kind, settings, prompt, key_points, active) values",
  rows.join(",\n"),
  "on conflict (id) do update set",
  "  category = excluded.category, kind = excluded.kind, settings = excluded.settings,",
  "  prompt = excluded.prompt, key_points = excluded.key_points, active = true;",
  "",
  "-- Questions removed from the source stay for history but are no longer picked.",
  `update public.interview_questions set active = false where key not in (${questions.map((q) => sql(q.key)).join(", ")});`,
  "",
].join("\n");

writeFileSync(OUTPUT, out);
const counts = Object.keys(categories).map((c) => `${c} ${questions.filter((q) => q.category === c).length}`);
console.log(`Wrote ${OUTPUT}: ${questions.length} questions (${counts.join(", ")})`);
